#include <Keypad.h>
#include <SPI.h>
#include <MFRC522.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <MPU6050.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

const byte ROWS = 4, COLS = 4;
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {13, 12, 14, 27};
byte colPins[COLS] = {26, 25, 33, 32};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

#define RFID_SS 5
#define RFID_RST 4
MFRC522 rfid(RFID_SS, RFID_RST);
byte correctUID[4] = {0xDE, 0xAD, 0xBE, 0xEF}; // replace with your tag's actual UID

MPU6050 mpu;

const int ldrPin = 34;
const int buzzerPin = 15;
const int greenLed = 2;
const int redLed = 16;

enum State { IDLE_ST, AUTH_ST, TILT_ST, LIGHT_ST, COMBO_ST, UNLOCKED_ST, FAILED_ST };
State currentState = IDLE_ST;

unsigned long stageStart = 0;
const unsigned long STAGE_TIMEOUT = 30000UL;

unsigned long tiltHoldStart = 0;
const unsigned long TILT_HOLD_REQUIRED = 3000UL;

int lightStep = 0;
const int LDR_DARK_THRESHOLD = 1500;   // ESP32 ADC is 12-bit (0-4095), recalibrate on your setup
const int LDR_LIGHT_THRESHOLD = 3000;

String secretCode = "";
String enteredCode = "";

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);

  pinMode(buzzerPin, OUTPUT);
  pinMode(greenLed, OUTPUT);
  pinMode(redLed, OUTPUT);

  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.display();

  SPI.begin(18, 19, 23, 5); // SCK, MISO, MOSI, SS
  rfid.PCD_Init();

  mpu.initialize();
  if (!mpu.testConnection()) {
    Serial.println("MPU6050 not found - check wiring");
  }

  randomSeed(analogRead(35));
  showMessage("Touch RFID", "to begin");
  stageStart = millis();
}

void loop() {
  switch (currentState) {
    case IDLE_ST:     handleIdle(); break;
    case AUTH_ST:     handleAuth(); break;
    case TILT_ST:     handleTilt(); break;
    case LIGHT_ST:    handleLight(); break;
    case COMBO_ST:    handleCombo(); break;
    case UNLOCKED_ST: handleUnlocked(); break;
    case FAILED_ST:   handleFailed(); break;
  }
  checkTimeout();
}

void showMessage(String line1, String line2) {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 20);
  display.println(line1);
  display.setCursor(0, 35);
  display.println(line2);
  display.display();
}

void beep(int freq, int dur) {
  tone(buzzerPin, freq, dur);
}

void wrongBuzz() {
  digitalWrite(redLed, HIGH);
  beep(200, 300);
  delay(300);
  digitalWrite(redLed, LOW);
}

void correctBeep() {
  digitalWrite(greenLed, HIGH);
  beep(1000, 150);
  delay(150);
  digitalWrite(greenLed, LOW);
}

void checkTimeout() {
  if (currentState != IDLE_ST && currentState != UNLOCKED_ST && currentState != FAILED_ST) {
    if (millis() - stageStart > STAGE_TIMEOUT) {
      currentState = FAILED_ST;
      stageStart = millis();
    }
  }
}

void resetGame() {
  currentState = IDLE_ST;
  lightStep = 0;
  enteredCode = "";
  showMessage("Touch RFID", "to begin");
  stageStart = millis();
}

void handleIdle() {
  currentState = AUTH_ST;
  stageStart = millis();
  showMessage("Scan RFID", "card now");
}

void handleAuth() {
  char key = keypad.getKey();
  if (key == 'D') { resetGame(); return; }

  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) return;

  bool match = true;
  for (byte i = 0; i < 4; i++) {
    if (rfid.uid.uidByte[i] != correctUID[i]) match = false;
  }

  if (match) {
    correctBeep();
    currentState = TILT_ST;
    stageStart = millis();
    tiltHoldStart = 0;
    showMessage("Hold box", "level & still");
  } else {
    wrongBuzz();
    showMessage("Wrong card", "try again");
  }
  rfid.PICC_HaltA();
}

void handleTilt() {
  char key = keypad.getKey();
  if (key == 'D') { resetGame(); return; }

  int16_t ax, ay, az;
  mpu.getAcceleration(&ax, &ay, &az);

  bool isLevel = (abs(ax) < 3000) && (abs(ay) < 3000);

  if (isLevel) {
    if (tiltHoldStart == 0) tiltHoldStart = millis();
    unsigned long held = millis() - tiltHoldStart;
    display.clearDisplay();
    display.setCursor(0, 20);
    display.print("Holding: ");
    display.print(held / 1000);
    display.println("s");
    display.display();

    if (held >= TILT_HOLD_REQUIRED) {
      correctBeep();
      currentState = LIGHT_ST;
      stageStart = millis();
      lightStep = 0;
      showMessage("Cover then", "uncover LDR");
    }
  } else {
    tiltHoldStart = 0;
  }
}

void handleLight() {
  char key = keypad.getKey();
  if (key == 'D') { resetGame(); return; }

  int lightVal = analogRead(ldrPin);

  if (lightStep == 0 && lightVal < LDR_DARK_THRESHOLD) {
    lightStep = 1;
    showMessage("Good - now", "uncover it");
  } else if (lightStep == 1 && lightVal > LDR_LIGHT_THRESHOLD) {
    lightStep = 2;
    showMessage("Good - cover", "once more");
  } else if (lightStep == 2 && lightVal < LDR_DARK_THRESHOLD) {
    correctBeep();
    currentState = COMBO_ST;
    stageStart = millis();
    enteredCode = "";
    secretCode = String(random(1000, 9999));
    showMessage("Code:", secretCode);
    delay(2500);
    showMessage("Enter code", "on keypad");
  }
}

void handleCombo() {
  char key = keypad.getKey();
  if (!key) return;

  if (key == 'D') { resetGame(); return; }

  if (key == '#') {
    if (enteredCode == secretCode) {
      currentState = UNLOCKED_ST;
      stageStart = millis();
    } else {
      wrongBuzz();
      enteredCode = "";
      showMessage("Wrong code", "try again");
    }
  } else if (key == '*') {
    enteredCode = "";
    showMessage("Enter code", "cleared");
  } else if (isDigit(key)) {
    enteredCode += key;
    showMessage("Code:", enteredCode);
  }
}

void handleUnlocked() {
  digitalWrite(greenLed, HIGH);
  showMessage("UNLOCKED!", "Well done");
  beep(1500, 200);
  delay(200);
  beep(2000, 200);
  delay(1000);
}

void handleFailed() {
  digitalWrite(redLed, HIGH);
  showMessage("TIME UP", "Press D to reset");
  beep(150, 500);
  delay(500);
  digitalWrite(redLed, LOW);
  delay(500);

  char key = keypad.getKey();
  if (key == 'D') resetGame();
}
